 t=R/'data/p13-20261026-formal'/r['id'];m=json.load(open(t/'run/metadata.json'));c=json.load(open(t/'candidate.json'));gz=next(p['command'] for p in m['processes'] if p['name']=='gazebo');seed=int(gz[gz.index('--seed')+1]);rows.append({'id':r['id'],'planned_seed':r['sim_seed'],'metadata_sim_seed':m['sim_seed'],'actual_Gazebo_argv_seed':seed,'seed_route_matches':seed==m['sim_seed']==r['sim_seed'],'metadata_project_commit':m['project_commit'],'candidate_project_head':c['project_head'],'runtime_project_head_matches_frozen':m['project_commit']==c['project_head']==freeze['commit'],'config_metadata_sha256':m['config_sha256'],'config_frozen_sha256':r['config_sha256'],'config_matches':m['config_sha256']==r['config_sha256'],'PX4_upstream_source_commit':m['source_commit'],'PX4_diff_sha256':m['source_diff_sha256'],'neural_policy_sha256':m['policy_sha256'],'universal_seed_warning_preserved':m['seed_scope']})
